const TARGET_VORGANGKEYS = ["vol_10631","vol_10639","vol_10646","vol_10660","vol_10640","vol_10654","vol_10616","vol_10641"];
function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }

const rows = $input.all().map(i => i.json || {});
const targets = rows.filter(r => TARGET_VORGANGKEYS.includes(safeStr(r.vorgangKey)));

if (targets.length !== TARGET_VORGANGKEYS.length) {
  const found = targets.map(r => r.vorgangKey);
  const missing = TARGET_VORGANGKEYS.filter(k => !found.includes(k));
  throw new Error('Nicht alle Ziel-Vorgaenge gefunden. Fehlend: ' + missing.join(', '));
}

return targets.map(r => ({ json: r }));

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
const j = $json;
return {
  json: {
    vorgangKey: safeStr(j.vorgangKey),
    vorgangsnummer: safeStr(j.vorgangsnummer),
    title: safeStr(j.title),
    sprengstoff: safeStr(j.sprengstoff),
    satireBrief: safeStr(j.satireBrief),
    satireAngle: safeStr(j.satireAngle),
    satirePunchlines: safeStr(j.satirePunchlines),
    imageHeadline: safeStr(j.imageHeadline),
    imageSubline: safeStr(j.imageSubline),
    pressStatementBisher: safeStr(j.pressStatement),
    absurdeForderung: safeStr(j.absurdeForderung)
  }
};

