function __repairJsonText(text) {
  var out = [];
  var inString = false, escaped = false;
  for (var i = 0; i < text.length; i++) {
    var ch = text[i];
    if (inString) {
      if (escaped) { out.push(ch); escaped = false; continue; }
      if (ch === '\\') { out.push(ch); escaped = true; continue; }
      if (ch === '"') { out.push(ch); inString = false; continue; }
      if (ch === '\n' || ch === '\r') {
        var rest = text.slice(i);
        var m = /^[\r\n]+\s*"[A-Za-z_][A-Za-z0-9_]*"\s*:/.exec(rest);
        if (m) {
          out.push('",'); inString = false; i += 1;
          while (i < text.length && (text[i] === '\r' || text[i] === '\n')) i++;
          i -= 1;
          continue;
        }
        out.push(ch === '\n' ? '\\n' : '\\r');
        continue;
      }
      if (ch === '\t') { out.push('\\t'); continue; }
      out.push(ch);
    } else {
      if (ch === '"') inString = true;
      out.push(ch);
    }
  }
  var stage1 = out.join('');

  var out2 = [];
  var stack = [];
  inString = false; escaped = false;
  var pairs = { '}': '{', ']': '[' };
  for (var j = 0; j < stage1.length; j++) {
    var c = stage1[j];
    if (inString) {
      out2.push(c);
      if (escaped) { escaped = false; }
      else if (c === '\\') { escaped = true; }
      else if (c === '"') { inString = false; }
      continue;
    }
    if (c === '"') { inString = true; out2.push(c); continue; }
    if (c === '{' || c === '[') { stack.push(c); out2.push(c); continue; }
    if (c === '}' || c === ']') {
      if (stack.length && stack[stack.length - 1] === pairs[c]) { stack.pop(); out2.push(c); }
      continue;
    }
    out2.push(c);
  }
  return out2.join('');
}

function __robustJsonParse(raw) {
  try {
    return JSON.parse(raw);
  } catch (e1) {
    try {
      return JSON.parse(__repairJsonText(raw));
    } catch (e2) {
      throw e1;
    }
  }
}

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function getAiText(j) {
  if (typeof j.content === 'string') return j.content;
  if (typeof j.text === 'string') return j.text;
  if (j.message && typeof j.message.content === 'string') return j.message.content;
  if (Array.isArray(j.choices) && j.choices[0] && j.choices[0].message) return safeStr(j.choices[0].message.content);
  if (Array.isArray(j.output)) {
    const msg = j.output.find(function(o) { return o && o.type === 'message' && Array.isArray(o.content); });
    const part = msg && msg.content.find(function(c) { return c && typeof c.text === 'string'; });
    if (part) return part.text;
  }
  return '';
}
const original = $('Baue Presseartikel-Eingabe').itemMatching($itemIndex).json;
const raw = $json;
let text = '';
try {
  const content = getAiText(raw);
  const cleaned = String(content).replace(/```json/gi, '').replace(/```/g, '').trim();
  const parsed = __robustJsonParse(cleaned);
  text = safeStr(parsed.pressStatement);
} catch (e) {}
// Statt bei einem einzelnen Fehlschlag den ganzen Reparaturlauf abzubrechen: dieses
// Item ueberspringen (repairSkipped=true, alter Text bleibt unangetastet), die uebrigen
// 7 trotzdem reparieren. Sicherheitscheck verhindert zusaetzlich, dass ein reparierter
// Text erneut versehentlich eine FREMDE Vorgangsnummer nennt (dieselbe Fehlerklasse,
// die hier gerade behoben wird).
const ownNumber = safeStr(original.vorgangsnummer);
const mentioned = (text.match(/2026\/\d{2,4}(-\d{1,2})?/g) || []);
const mentionsOther = mentioned.some(m => m !== ownNumber);
const looksWrong = mentioned.length > 0 && !mentioned.includes(ownNumber) && mentionsOther;

if (!text || looksWrong) {
  return { json: { ...original, pressStatementFinal: original.pressStatementBisher, repairSkipped: true, repairSkipReason: !text ? 'keine gueltige AI-Antwort' : ('neu erzeugter Text nennt fremde Nummer: ' + mentioned.join(', ')) } };
}

return { json: { ...original, pressStatementFinal: text, repairSkipped: false } };
